/* Structured N4 course; all records share the study archive and cloud document. */
state=cleanState({...state,...cleanStudyExtras(startupStudyRecord||state)});
const n4Unit=id=>N4_UNITS.find(u=>u.id===id);
function n4State(u){return state.n4.units[u.id]??={done:[],ratings:[],answers:{},review:{},draft:''};}
const n4Next=()=>N4_UNITS.find(u=>!n4State(u).done.includes('review'))||N4_UNITS.at(-1);
const n4Ids=u=>[...u.grammarIds,...u.reading.ids,...u.listening.ids];
const n4FinalIds=()=>N4_UNITS.flatMap((u,i)=>[u.grammarIds[i%2],u[i%2?'reading':'listening'].id]);
const n4Pct=()=>Math.round(N4_UNITS.reduce((n,u)=>n+n4State(u).done.length,0)/(N4_UNITS.length*N4_STAGES.length)*100);
let n4Guided=false;
function n4Favorite(k){return `<button class="favorite-toggle secondary" data-favorite="${esc(k)}" aria-pressed="${state.favorites.includes(k)}">${state.favorites.includes(k)?'★ 已收藏':'☆ 收藏'}</button>`;}
function n4Question(id,map,kind){const q=questionById(id),a=map[id],answered=Number.isInteger(a);return `<article class="n5-question"><h3>${esc(q.q)}</h3><div class="answers">${q.options.map((o,i)=>`<button data-n4answer="${id}" data-kind="${kind}" data-value="${i}" ${answered?'disabled':''} class="${answered&&i===q.answer?'correct':answered&&a===i?'wrong':''}">${esc(o)}</button>`).join('')}</div>${answered?`<p class="feedback">${a===q.answer?'✓ 正确':'再理解一次'} · ${esc(q.why)}</p>`:''}</article>`;}
function n4CanFinish(u,k){const s=n4State(u);if(k==='words')return u.wordIds.every(id=>s.ratings.includes(id));const ids=k==='grammar'?u.grammarIds:k==='review'?n4Ids(u):u[k].ids,map=k==='review'?s.review:s.answers;return ids.every(id=>Number.isInteger(map[id]))&&(k!=='review'||N4_STAGES.slice(0,4).every(k=>s.done.includes(k))&&ids.filter(id=>map[id]===questionById(id).answer).length/ids.length>=.8);}
function n4Daily(){let day=state.n4.day;if(!day){const u=n4Next(),stages=N4_STAGES.filter(k=>!n4State(u).done.includes(k)).slice(0,state.plan.minutes===20?1:state.plan.minutes===60?3:2);state.n4.day=day={unit:u.id,stages:stages.length?stages:['review']};persist();}return day;}
function n4DailyHtml(home=false){const d=n4Daily(),u=n4Unit(d.unit),s=n4State(u),all=d.stages.every(k=>s.done.includes(k)),active=d.stages.find(k=>!s.done.includes(k));return `<section class="container page-section"><div class="dash-section-head"><h2>今日 N4 学习</h2><span>${state.plan.minutes} 分钟 · 第 ${N4_UNITS.indexOf(u)+1} 单元</span></div><h3>${esc(u.title)}</h3><div class="dash-task-list">${d.stages.map((k,i)=>`<button class="dash-task ${s.done.includes(k)?'is-done':k===active?'is-current':'is-pending'}" data-n4daily="${k}" ${!all&&k!==active&&!s.done.includes(k)?'disabled':''}><span class="dash-task-number">${s.done.includes(k)?'✓':i+1}</span><strong>${N4_STAGE_LABELS[k]}</strong></button>`).join('')}</div>${all?'<button class="primary" id="n4NextDay">开始下一学习日 →</button>':''}${!home?'<div class="toolbar"><button class="secondary" data-page="lessons" data-level="N4">全部 N4 课程</button><button class="secondary" id="n4Budget">调整每日时间</button></div><p>词汇 → 句型 → 阅读 → 听力 → 复习。未完成任务会保留。</p>':''}</section>`;}
function n4Overview(){return title('','N4 系统课程','')+`<section class="container page-section"><div class="n5-course-hero"><div><h2>把基础日语用进生活</h2><p>24 个主题单元，按词汇、句型、阅读、听力和复习推进。</p><button class="primary" data-n4unit="${n4Next().id}">继续下一单元 →</button><button class="secondary" id="n4UsePlan">安排 N4 每日学习</button><button class="secondary" id="n4Final">结课测评</button></div><div><b>${n4Pct()}%</b><p>${N4_UNITS.filter(u=>n4State(u).done.includes('review')).length}/24 单元通过</p></div></div><details class="learning-help"><summary>课程范围与使用方法</summary><p>接续 N5 的原创系统教学选编，含 48 个句型讲解、96 组例句、24 篇阅读和24段合成语音对话，每篇3题。并非官方固定考纲，也不代替完整词汇积累或真人录音训练。每单元复习须先完成前四步，并达到 80%。</p><a href="https://www.jlpt.jp/e/about/levelsummary.html" target="_blank" rel="noopener">JLPT 官方能力说明 ↗</a></details><div class="sectionhead"><h2>补充语法与专题练习</h2></div><div class="n4-focus"><button class="secondary" data-n4focus="conditions">条件与让步</button><button class="secondary" data-n4focus="help">授受与礼貌</button><button class="secondary" data-n4focus="voice">被动、使役与敬语</button><button class="secondary" data-n4focus="supplement">新增语法练习</button></div><details class="learning-help"><summary>打开 8 节补充语法</summary><div class="n4-supp-grid">${N4_SUPPLEMENT.map(g=>`<button class="secondary" data-lesson="${g.id}">${esc(g.title)} →</button>`).join('')}</div></details><div class="sectionhead"><h2>24 个主题单元</h2></div><div class="n5-unit-grid">${N4_UNITS.map((u,i)=>{const s=n4State(u);return `<button class="n5-unit-card" data-n4unit="${u.id}"><span class="label">第 ${i+1} 单元</span><span class="n5-badge">${s.done.includes('review')?'✓ 已通过':s.done.length||s.ratings.length?'◐ 学习中':'○ 未开始'}</span><h3>${esc(u.title)}</h3><div class="bar"><div style="width:${s.done.length/5*100}%"></div></div><span>${s.done.length}/5 步骤 · 打开 →</span></button>`;}).join('')}</div></section>`;}
function n4UnitHtml(u){const s=n4State(u),k=state.n4.stage;let body='';if(k==='words')body=`<div class="n5-word-grid">${u.wordIds.map(id=>{const w=words.find(w=>w.id===id);return `<article class="n5-word"><h3 lang="ja">${esc(w.word)}</h3>${n4Favorite('word:'+id)}<details data-expand-reading="${esc(w.reading)}"><summary>展开读音与词义</summary><p>${esc(w.reading)}</p>${romanLine(w.reading)}<p class="vocab-meaning"><strong>${esc(w.meaning)}</strong></p><span class="pos-badge">${esc(w.pos)}</span><button data-speak="${esc(w.reading)}" class="secondary">▷ 听读音</button><div class="toolbar"><button class="secondary" data-n4rate="${id}" data-value="0">还不熟</button><button class="primary" data-n4rate="${id}" data-value="1">${s.ratings.includes(id)?'✓ 已自评':'记住了'}</button></div></details></article>`;}).join('')}</div>`;
if(k==='grammar')body=u.grammar.map(g=>`<article class="n5-grammar"><h2>${esc(g.title)}</h2>${n4Favorite('grammar:'+g.id)}<p>${esc(g.rule)}</p>${g.examples.map(([ja,kana,zh],i)=>`<div class="example"><b lang="ja">${esc(ja)}</b><p>${esc(kana)}</p>${romanLine(kana,true)}<p>${esc(zh)}</p><button class="secondary" data-speak="${esc(ja)}">▷ 跟读</button>${n4Favorite('example:'+g.id+':'+i)}</div>`).join('')}<div class="hint">易错点：${esc(g.pitfall)}</div>${n4Question(g.id,s.answers,'answers')}</article>`).join('');
if(k==='reading'||k==='listening'){const t=u[k];body=`<article class="n5-text"><h2>${esc(u.title)} · ${N4_STAGE_LABELS[k]}</h2>${k==='listening'?`<button class="primary" data-speak="${esc(t.text)}">▷ 播放对话</button><p>合成语音，可在顶部选择日语声音。</p><details><summary>展开听力原文</summary><p class="japanese-text">${esc(t.text)}</p></details>`:`<p class="japanese-text">${esc(t.text)}</p>`}<details><summary>查看中文对照</summary><p>${esc(t.translation)}</p></details>${t.ids.map(id=>n4Question(id,s.answers,'answers')).join('')}</article>`;}
if(k==='review')body='<p>8 题覆盖句型、阅读和听力；答对至少 7 题后通过。</p>'+u.grammarIds.map(id=>n4Question(id,s.review,'review')).join('')+['reading','listening'].map(kind=>{const t=u[kind];return `<article class="n5-text"><h3>${N4_STAGE_LABELS[kind]}</h3>${kind==='listening'?`<button class="secondary" data-speak="${esc(t.text)}">▷ 播放对话</button>`:''}<details><summary>查看原文</summary><p class="japanese-text">${esc(t.text)}</p></details>${t.ids.map(id=>n4Question(id,s.review,'review')).join('')}</article>`;}).join('');
return title('','N4 · '+u.title,'')+`<section class="container page-section"><div class="toolbar"><button class="secondary" id="n4Back">← 全部单元</button><button class="secondary" data-page="plan" data-level="N4">每日计划</button></div><div class="n5-stage-tabs">${N4_STAGES.map((st,i)=>`<button data-n4stage="${st}" class="${st===k?'selected':''}">${s.done.includes(st)?'✓':i+1} ${N4_STAGE_LABELS[st]}</button>`).join('')}</div>${body}<details class="learning-help"><summary>本次内容扩充说明</summary><p>词汇扩充为每单元12条，阅读和听力各3题。已完成的步骤保留原记录；可以自由补做新增练习。</p></details><div class="n5-finish"><p>${s.done.includes(k)?'✓ 本步已完成':k==='review'?'完成前四步并达到 80% 后通过':'完成本步全部练习后继续'}</p><button class="primary" id="n4Finish" ${!n4CanFinish(u,k)?'disabled':''}>完成本步，继续 →</button>${k!=='words'?'<button class="secondary" id="n4Retry">重做本步练习</button>':''}</div><details class="writing-panel"><summary>可选写作 · 用本课句型写两句话</summary><textarea id="n4Draft" maxlength="4000">${esc(s.draft)}</textarea><p id="n4DraftStatus">草稿自动保存</p><details><summary>参考表达与自查</summary><p>请分别使用「${esc(u.grammar[0].title)}」和「${esc(u.grammar[1].title)}」描述自己的生活。</p>${u.grammar.map(g=>`<p lang="ja">${esc(g.examples[1][0])}</p><p>${esc(g.examples[1][2])}</p>`).join('')}<p>检查接续、助词与时态，再将例句中的人物或场景换成自己的信息。</p></details></details></section>`;}
function n4FinalHtml(){const f=state.n4.final,ids=n4FinalIds(),answered=ids.filter(id=>Number.isInteger(f.answers[id])).length,score=Math.round(ids.filter(id=>f.answers[id]===questionById(id).answer).length/ids.length*100);return title('','N4 结课测评','')+`<section class="container page-section"><button class="secondary" id="n4Back">← 全部单元</button><p>48 题 · 句型、阅读与听力 · 已答 ${answered}/48</p>${f.submitted?`<h2>正确率 ${score}%</h2>${score>=80?'<button class="primary" data-page="lessons" data-level="N3">前往 N3 核心练习 →</button>':''}<button class="secondary" id="n4ResetFinal">开始新一轮测评</button>`:''}${ids.map(id=>{const q=questionById(id);return (q.text?(q.type==='listening'?`<button class="secondary" data-speak="${esc(q.text)}">▷ 播放听力</button><details><summary>听后查看原文</summary><p class="japanese-text">${esc(q.text)}</p></details>`:`<p class="japanese-text">${esc(q.text)}</p>`):'')+(f.submitted?`<div class="hint">${f.answers[id]===q.answer?'✓':'✕'} ${esc(q.q)}<p>答案：${esc(q.options[q.answer])} · ${esc(q.why)}</p></div>`:n4Question(id,f.answers,'final'));}).join('')}${!f.submitted?`<button class="primary" id="n4SubmitFinal" ${answered<ids.length?'disabled':''}>交卷并查看解析</button>`:''}</section>`;}
let n4FinalOpen=false;
const n4PreviousLessons=renderLessons;renderLessons=function(isGrammar=false){if(level!=='N4'||isGrammar)return n4PreviousLessons(isGrammar);return n4FinalOpen?n4FinalHtml():state.n4.cursor?n4UnitHtml(n4Unit(state.n4.cursor)):n4Overview();};
const n4PreviousPlan=renderPlan;renderPlan=function(){return level==='N4'||state.plan.start==='N4'||state.guide.day?.level==='N4'?title('','N4 每日计划','')+n4DailyHtml():n4PreviousPlan();};
const n4PreviousHome=renderHome;renderHome=function(){let html=n4PreviousHome().replace('N4</strong><span>核心练习','N4</strong><span>系统课程');if(level==='N4'){const u=n4Unit(state.n4.cursor)||n4Next();html=html.replace(esc(nextGrammar('N4').title),esc(u.title)).replace(`data-lesson="${nextGrammar('N4').id}"`,`data-n4unit="${u.id}"`).replace(/<section class="container dash-today">[\s\S]*?<\/section>/,n4DailyHtml(true));}return html;};
const n4PreviousProgress=dashboardProgress;dashboardProgress=function(l){return l==='N4'?n4Pct():n4PreviousProgress(l);};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;
if(d.n4focus){if(state.activeQuiz){go('practice',state.activeQuiz.level);toast('先完成或结束当前练习。');return;}const groups={conditions:[7,8,9],help:[12,13],voice:[16,17,18,19]};const ids=d.n4focus==='supplement'?N4_SUPPLEMENT.map(g=>g.id):(groups[d.n4focus]||[]).flatMap(i=>[...N4_UNITS[i].grammarIds,N4_UNITS[i].reading.ids[1],N4_UNITS[i].listening.ids[1]]);if(!ids.length)return;guideActive=false;level='N4';state.activeQuiz={level:'N4',mode:'grammar',ids:shuffled(ids).slice(0,12),answers:[],index:0};persist();go('practice','N4');}
if(d.n4unit){const u=n4Unit(d.n4unit);if(!u)return;state.n4.cursor=u.id;state.n4.stage=N4_STAGES.includes(d.n4open)?d.n4open:N4_STAGES.find(k=>!n4State(u).done.includes(k))||'review';n4FinalOpen=false;n4Guided=false;persist();go('lessons','N4');}
if(d.n4stage){state.n4.stage=d.n4stage;persist();render(false);}
if(d.n4daily){const day=n4Daily();state.n4.cursor=day.unit;state.n4.stage=d.n4daily;n4Guided=true;persist();go('lessons','N4');}
if(b.id==='n4Back'){state.n4.cursor=null;n4FinalOpen=false;persist();render(false);}
if(b.id==='n4UsePlan'){state.plan.start='N4';if(state.plan.target==='N5')state.plan.target='N4';state.guide.day=null;persist();go('plan','N4');}
if(b.id==='n4NextDay'){const d=n4Daily();if(d.stages.every(k=>n4State(n4Unit(d.unit)).done.includes(k))){state.n4.day=null;persist();render(false);}}
if(b.id==='n4Budget'){const vals=[20,40,60];state.plan.minutes=vals[(vals.indexOf(state.plan.minutes)+1)%3];persist();render(false);toast('每天 '+state.plan.minutes+' 分钟，下个学习日生效。');}
if(d.n4answer){const q=questionById(d.n4answer),a=Number(d.value);if(!q||!q.options[a])return;const map=d.kind==='final'?state.n4.final.answers:n4State(n4Unit(state.n4.cursor))[d.kind];if(map[q.id]!==undefined)return;map[q.id]=a;recordAnswer(q,a);persist();render(false);}
if(d.n4rate){const u=n4Unit(state.n4.cursor),s=n4State(u);s.ratings=[...new Set([...s.ratings,d.n4rate])];const old=state.wordReviews[d.n4rate],box=d.value==='1'?old?.last===dateKey()?Math.max(old.box,1):Math.min((old?.box||0)+1,6):0;state.wordReviews[d.n4rate]={box,due:box?afterDays([1,3,7,14,30,60][box-1]):dateKey(),last:dateKey()};touch('vocab');persist();b.textContent=d.value==='1'?'✓ 已记住':'↺ 待巩固';$('#n4Finish').disabled=!n4CanFinish(u,'words');}
if(b.id==='n4Finish'){const u=n4Unit(state.n4.cursor),k=state.n4.stage,s=n4State(u);if(!n4CanFinish(u,k))return;if(!s.done.includes(k)){s.done.push(k);if(k==='grammar')u.grammarIds.forEach(markLesson);if(k==='reading'||k==='listening'){state.textDone=[...new Set([...state.textDone,...u[k].ids])];touch(k);}if(k==='review')touch('practice');}const next=N4_STAGES[N4_STAGES.indexOf(k)+1];if(next)state.n4.stage=next;persist();if(n4Guided)go('plan','N4');else render(false);toast('本步已保存。');}
if(b.id==='n4Retry'){const s=n4State(n4Unit(state.n4.cursor)),k=state.n4.stage;for(const id of k==='grammar'?n4Unit(state.n4.cursor).grammarIds:k==='review'?n4Ids(n4Unit(state.n4.cursor)):n4Unit(state.n4.cursor)[k].ids)delete (k==='review'?s.review:s.answers)[id];persist();render(false);}
if(b.id==='n4Final'){n4FinalOpen=true;render(false);}
if(b.id==='n4SubmitFinal'){if(n4FinalIds().every(id=>Number.isInteger(state.n4.final.answers[id]))){state.n4.final.submitted=true;persist();render(false);}}
if(b.id==='n4ResetFinal'){state.n4.final={answers:{},submitted:false};persist();render(false);}
});
document.addEventListener('input',e=>{if(e.target.id==='n4Draft'){n4State(n4Unit(state.n4.cursor)).draft=e.target.value;persist();$('#n4DraftStatus').textContent='✓ 草稿已保存';}});
render(false);

const n4OriginalTexts=renderTexts;
renderTexts=function(type){if(level!=='N4')return n4OriginalTexts(type);const old=(type==='reading'?readings:listenings).filter(q=>q.level==='N4'&&!q.unit);return title('',type==='reading'?'N4 阅读训练':'N4 听力训练','')+`<section class="container page-section"><p>24 个生活主题，每篇 3 道理解题。</p><div class="n5-unit-grid">${N4_UNITS.map((u,i)=>`<button class="n5-unit-card" data-n4unit="${u.id}" data-n4open="${type}"><span class="label">第 ${i+1} 单元</span><h3>${esc(u.title)}</h3><span class="n5-badge">${n4State(u).done.includes(type)?'✓ 已完成':'○ 待学习'}</span><p>打开课文与 3 道练习 →</p></button>`).join('')}</div><details class="learning-help"><summary>之前的入门篇章</summary>${old.map(q=>`<article class="text-card"><h3>${esc(q.title)}</h3>${type==='listening'?`<button class="secondary" data-speak="${esc(q.text)}">▷ 播放</button>`:''}<p class="japanese-text">${esc(q.text)}</p><details><summary>中文对照</summary><p>${esc(q.translation)}</p></details>${answerBlock(q)}<button class="secondary" data-textdone="${q.id}" disabled>完成并记录</button></article>`).join('')}</details></section>`;};
